import random
import string
from typing import List

# Target data type: log level name string for spdlog level parsers.
# We generate interesting, valid configuration/text cases that exercise:
# - Exact canonical names
# - Common aliases (warning/error)
# - Case variants
# - Mixed whitespace and separators
# - Combined cfg strings for env/argv helpers
# - Per-logger mappings and global overrides
# - Short and longer inputs, but always valid UTF-8 bytes
# The fuzzing harness will pull a string/filename; we provide a single bytes buffer
# that the fuzzer framework can split/consume. We include multiple newline-separated
# candidates so FUZZ_PARAM_STR reads diverse slices depending on engine behavior.

LEVELS = [
    "trace", "debug", "info", "warn", "warning", "err", "error", "critical", "off"
]

# Some logger names to pair with levels
LOGGER_NAMES = [
    "root", "app", "net", "db", "worker", "io", "parser", "UI", "A", "B",
]

SEPARATORS = [",", " ,", ", ", ",\t", ",\n", ";", " "]

def rand_level(r: random.Random) -> str:
    return r.choice(LEVELS)

def rand_logger(r: random.Random) -> str:
    base = r.choice(LOGGER_NAMES)
    # optionally append a suffix
    if r.random() < 0.5:
        base += str(r.randint(0, 9))
    # sanitize to allowed chars [A-Za-z0-9_-]
    ok = string.ascii_letters + string.digits + "-_"
    return "".join(ch if ch in ok else '_' for ch in base)[:32] or "logger"

def case_variant(r: random.Random, s: str) -> str:
    mode = r.randint(0, 3)
    if mode == 0:
        return s.lower()
    if mode == 1:
        return s.upper()
    if mode == 2:
        return s.capitalize()
    # random per-char case
    return ''.join(c.upper() if r.random() < 0.5 else c.lower() for c in s)

def make_from_str_samples(r: random.Random) -> List[str]:
    samples = []
    # Canonical levels and aliases
    for lv in LEVELS:
        samples.append(lv)
        samples.append(case_variant(r, lv))
    # With surrounding whitespace
    for lv in LEVELS:
        ws_left = "".join(r.choice([" ", "\t"]) for _ in range(r.randint(0, 3)))
        ws_right = "".join(r.choice([" ", "\t"]) for _ in range(r.randint(0, 3)))
        samples.append(f"{ws_left}{case_variant(r, lv)}{ws_right}")
    # With plus/minus punctuation that parser may ignore or treat as error (still valid string)
    for lv in ["warn", "error", "info"]:
        samples.append(f"{case_variant(r, lv)}\n")
    # Short random valid tokens built from letters
    alpha = string.ascii_letters
    for _ in range(5):
        s = ''.join(r.choice(alpha) for _ in range(r.randint(3, 8)))
        samples.append(s)
    return samples

def make_cfg_string(r: random.Random, max_items: int) -> str:
    # Compose comma-separated items: either global level or name=level
    n = r.randint(1, max_items)
    parts = []
    for i in range(n):
        if r.random() < 0.5:
            parts.append(case_variant(r, rand_level(r)))
        else:
            parts.append(f"{rand_logger(r)}={case_variant(r, rand_level(r))}")
    # optionally include explicit global directive "*="
    if r.random() < 0.5:
        parts.insert(r.randrange(len(parts)+1), f"*={case_variant(r, rand_level(r))}")
    # join with varied separators to exercise parser flexibility
    sep = r.choice(SEPARATORS)
    return sep.join(parts)

def make_env_blob(r: random.Random) -> str:
    # Build several environment-like lines
    lines = []
    # default var name
    lines.append("SPDLOG_LEVEL=" + make_cfg_string(r, 4))
    # custom var names uppercase with underscores
    for _ in range(r.randint(0, 2)):
        name = "SPDLOG_LEVEL" if r.random() < 0.4 else (
            "SP_" + ''.join(r.choice(string.ascii_uppercase + string.digits + "_") for _ in range(r.randint(4, 10)))
        )
        lines.append(name + "=" + make_cfg_string(r, 5))
    return "\n".join(lines)

def make_argv_blob(r: random.Random) -> str:
    # Simulate argv entries; first token like program name, then an SPDLOG_LEVEL=...
    prog = "/bin/prog" if r.random() < 0.5 else "prog"
    cfg = "SPDLOG_LEVEL=" + make_cfg_string(r, 4)
    extras = []
    for _ in range(r.randint(0, 2)):
        extras.append(''.join(r.choice(string.ascii_letters + string.digits + "-_./") for _ in range(r.randint(1, 12))))
    return "\n".join([prog, cfg] + extras)

def build_blob(r: random.Random) -> bytes:
    sections = []
    # Section 1: plain level tokens (for from_str)
    sections.append("#levels")
    sections.extend(make_from_str_samples(r))

    # Section 2: env configs
    sections.append("#env")
    sections.append(make_env_blob(r))

    # Section 3: argv configs
    sections.append("#argv")
    sections.append(make_argv_blob(r))

    # Section 4: helpers::load_levels configs (multiple lines)
    sections.append("#helpers")
    for _ in range(r.randint(1, 3)):
        sections.append(make_cfg_string(r, 6))

    # Join with newlines; cap size to 4096 bytes
    data = ("\n".join(sections)).encode('utf-8', errors='ignore')
    return data[:4096]


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    return build_blob(r)
